const norm = (s: string) =>
  s.toLowerCase()
    .replace(/\u0153/g, "oe").replace(/\u00e6/g, "ae")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "");

export function searchMarmitonRecipes(query: string): MarmitonRecipe[] {
  if (!query.trim()) return MARMITON_RECIPES;
  const q = norm(query.trim());
  return MARMITON_RECIPES.filter((r) => {
    if (norm(r.name).includes(q)) return true;
    return r.ingredients.some((i) => norm(i.name).includes(q));
  });
}